using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;

const string sheetPath = "Assets/Flynn/Sprites/character_animations/FINAL_ANIMATIONS/RUN_NEW/Run.png";
const string animOut   = "Assets/Flynn/Animations";
const float  fps       = 12f;

var allSprites = AssetDatabase.LoadAllAssetRepresentationsAtPath(sheetPath)
    .OfType<Sprite>()
    .OrderBy(s => s.name, new NumericNameComparer())
    .ToArray();

Debug.Log($"[RunClips] Loaded {allSprites.Length} sprites from sheet");

if (allSprites.Length < 24)
{
    Debug.LogError($"[RunClips] Expected 24 sprites, got {allSprites.Length}");
    return;
}

// Row 0 (Down): 0-7, Row 1 (Up): 8-15, Row 2 (Left): 16-23
var defs = new (string clipName, int start, int count)[]
{
    ("Flynn_Run_Down", 0,  8),
    ("Flynn_Run_Up",   8,  8),
    ("Flynn_Run_Left", 16, 8),
};

foreach (var (clipName, start, count) in defs)
{
    var clip = new AnimationClip { frameRate = fps };

    var binding = new EditorCurveBinding
    {
        type         = typeof(SpriteRenderer),
        path         = "",
        propertyName = "m_Sprite"
    };

    var keys = new ObjectReferenceKeyframe[count];
    for (int i = 0; i < count; i++)
        keys[i] = new ObjectReferenceKeyframe { time = i / fps, value = allSprites[start + i] };

    AnimationUtility.SetObjectReferenceCurve(clip, binding, keys);

    var settings = AnimationUtility.GetAnimationClipSettings(clip);
    settings.loopTime = true;
    AnimationUtility.SetAnimationClipSettings(clip, settings);
    clip.wrapMode = WrapMode.Loop;

    string outPath = $"{animOut}/{clipName}.anim";
    if (AssetDatabase.LoadAssetAtPath<AnimationClip>(outPath) != null)
        AssetDatabase.DeleteAsset(outPath);

    AssetDatabase.CreateAsset(clip, outPath);
    EditorUtility.SetDirty(clip);
    Debug.Log($"[RunClips] Created '{clipName}' ({count} frames from sprites {start}-{start+count-1})");
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("[RunClips] All run clips created.");

class NumericNameComparer : IComparer<string>
{
    public int Compare(string a, string b)
    {
        int na = int.TryParse(a.Replace("Run_", ""), out var ia) ? ia : 0;
        int nb = int.TryParse(b.Replace("Run_", ""), out var ib) ? ib : 0;
        return na.CompareTo(nb);
    }
}

