using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;

const string ctrlPath = "Assets/Flynn/Animations/Flynn_FrameAnimator.controller";

if (AssetDatabase.LoadAssetAtPath<AnimatorController>(ctrlPath) != null)
    AssetDatabase.DeleteAsset(ctrlPath);

var ctrl = AnimatorController.CreateAnimatorControllerAtPath(ctrlPath);
ctrl.AddParameter("Speed",      AnimatorControllerParameterType.Float);
ctrl.AddParameter("IsGrounded", AnimatorControllerParameterType.Bool);
ctrl.AddParameter("FacingDir",  AnimatorControllerParameterType.Float);
ctrl.AddParameter("Jump",       AnimatorControllerParameterType.Trigger);
ctrl.AddParameter("Swing",      AnimatorControllerParameterType.Trigger);
ctrl.AddParameter("Hold",        AnimatorControllerParameterType.Bool);
ctrl.AddParameter("Throw",      AnimatorControllerParameterType.Trigger);
ctrl.AddParameter("Scan",       AnimatorControllerParameterType.Trigger);

var sm = ctrl.layers[0].stateMachine;

AnimationClip Clip(string name) => AssetDatabase.LoadAssetAtPath<AnimationClip>($"Assets/Flynn/Animations/{name}.anim");

BlendTree MakeDirTree(string action)
{
    var tree = new BlendTree
    {
        name = $"{action}_Tree",
        blendType = BlendTreeType.Simple1D,
        blendParameter = "FacingDir",
        useAutomaticThresholds = false
    };
    var children = new List<ChildMotion>();
    var cDown = Clip($"Flynn_{action}_Down");
    var cUp   = Clip($"Flynn_{action}_Up");
    var cLeft = Clip($"Flynn_{action}_Left");
    if (cDown != null) children.Add(new ChildMotion { motion = cDown, threshold = 0f, timeScale = 1f });
    else Debug.LogWarning($"[FrameAnimator] Missing: Flynn_{action}_Down");
    if (cUp != null)   children.Add(new ChildMotion { motion = cUp,   threshold = 1f, timeScale = 1f });
    else Debug.LogWarning($"[FrameAnimator] Missing: Flynn_{action}_Up");
    if (cLeft != null) children.Add(new ChildMotion { motion = cLeft, threshold = 2f, timeScale = 1f });
    else Debug.LogWarning($"[FrameAnimator] Missing: Flynn_{action}_Left");
    tree.children = children.ToArray();
    return tree;
}

var idleTree  = MakeDirTree("Idle");
var runTree   = MakeDirTree("Run");
var jumpTree  = MakeDirTree("Jump");
var swingTree = MakeDirTree("Swing");
var holdTree  = MakeDirTree("Hold");
var throwTree = MakeDirTree("Throw");
var scanTree  = MakeDirTree("Scan");

AssetDatabase.AddObjectToAsset(idleTree, ctrl);
AssetDatabase.AddObjectToAsset(runTree, ctrl);
AssetDatabase.AddObjectToAsset(jumpTree, ctrl);
AssetDatabase.AddObjectToAsset(swingTree, ctrl);
AssetDatabase.AddObjectToAsset(holdTree, ctrl);
AssetDatabase.AddObjectToAsset(throwTree, ctrl);
AssetDatabase.AddObjectToAsset(scanTree, ctrl);

var idleState  = sm.AddState("Idle",  new Vector3(200, 100, 0));
var runState   = sm.AddState("Run",   new Vector3(200, 250, 0));
var jumpState  = sm.AddState("Jump",  new Vector3(500, 100, 0));
var swingState = sm.AddState("Swing", new Vector3(500, 250, 0));
var holdState  = sm.AddState("Hold",  new Vector3(200, 400, 0));
var throwState = sm.AddState("Throw", new Vector3(500, 400, 0));
var scanState  = sm.AddState("Scan",  new Vector3(500, 550, 0));

idleState.motion  = idleTree;
runState.motion   = runTree;
jumpState.motion  = jumpTree;
swingState.motion = swingTree;
holdState.motion  = holdTree;
throwState.motion = throwTree;
scanState.motion  = scanTree;

swingState.tag = "Attack";
sm.defaultState = idleState;

AnimatorStateTransition MkTrans(AnimatorState from, AnimatorState to)
{
    var t = from.AddTransition(to);
    t.hasExitTime = false; t.duration = 0f; t.exitTime = 0f;
    return t;
}

var t = MkTrans(idleState, runState);
t.AddCondition(AnimatorConditionMode.Greater, 0.1f, "Speed");
t = MkTrans(runState, idleState);
t.AddCondition(AnimatorConditionMode.Less, 0.1f, "Speed");

t = MkTrans(idleState, jumpState);
t.AddCondition(AnimatorConditionMode.IfNot, 0f, "IsGrounded");
t = MkTrans(runState, jumpState);
t.AddCondition(AnimatorConditionMode.IfNot, 0f, "IsGrounded");
t = MkTrans(jumpState, idleState);
t.AddCondition(AnimatorConditionMode.If, 0f, "IsGrounded");

var anySwing = sm.AddAnyStateTransition(swingState);
anySwing.hasExitTime = false; anySwing.duration = 0f; anySwing.canTransitionToSelf = false;
anySwing.AddCondition(AnimatorConditionMode.If, 0f, "Swing");
var swingExit = swingState.AddTransition(idleState);
swingExit.hasExitTime = true; swingExit.exitTime = 0.85f; swingExit.duration = 0f;

var anyThrow = sm.AddAnyStateTransition(throwState);
anyThrow.hasExitTime = false; anyThrow.duration = 0f; anyThrow.canTransitionToSelf = false;
anyThrow.AddCondition(AnimatorConditionMode.If, 0f, "Throw");
var throwExit = throwState.AddTransition(idleState);
throwExit.hasExitTime = true; throwExit.exitTime = 0.85f; throwExit.duration = 0f;

var anyScan = sm.AddAnyStateTransition(scanState);
anyScan.hasExitTime = false; anyScan.duration = 0f; anyScan.canTransitionToSelf = false;
anyScan.AddCondition(AnimatorConditionMode.If, 0f, "Scan");
var scanExit = scanState.AddTransition(idleState);
scanExit.hasExitTime = true; scanExit.exitTime = 0.85f; scanExit.duration = 0f;

t = MkTrans(idleState, holdState);
t.AddCondition(AnimatorConditionMode.If, 0f, "Hold");
t = MkTrans(runState, holdState);
t.AddCondition(AnimatorConditionMode.If, 0f, "Hold");
t = MkTrans(holdState, idleState);
t.AddCondition(AnimatorConditionMode.IfNot, 0f, "Hold");
t.AddCondition(AnimatorConditionMode.Less, 0.1f, "Speed");
t = MkTrans(holdState, runState);
t.AddCondition(AnimatorConditionMode.IfNot, 0f, "Hold");
t.AddCondition(AnimatorConditionMode.Greater, 0.1f, "Speed");

var anyJump = sm.AddAnyStateTransition(jumpState);
anyJump.hasExitTime = false; anyJump.duration = 0f; anyJump.canTransitionToSelf = false;
anyJump.AddCondition(AnimatorConditionMode.If, 0f, "Jump");

EditorUtility.SetDirty(ctrl);
AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("[FrameAnimator] Rebuilt — all clips (Idle/Run/Jump/Swing/Hold/Throw/Scan) with 3-direction blend trees.");

