using UnityEngine;
using UnityEditor;
using System.Linq;

const string assetPath = "Assets/Flynn/Sprites/character_animations/FINAL_ANIMATIONS/RUN_NEW/Run.png";
const int cols = 8;
const int rows = 3;
const int framesPerRow = 8;

var importer = (TextureImporter)AssetImporter.GetAtPath(assetPath);
if (importer == null) { Debug.LogError("Importer not found"); return; }

// Read existing sprite metadata to get sprite IDs
var existingSprites = new Dictionary<string, SpriteMeta>();
var so = new SerializedObject(importer);
var spriteSheetProp = so.FindProperty("m_SpriteSheet.m_Sprites");
for (int i = 0; i < spriteSheetProp.arraySize; i++)
{
    var sp = spriteSheetProp.GetArrayElementAtIndex(i);
    var name = sp.FindPropertyRelative("m_Name").stringValue;
    var sid = sp.FindPropertyRelative("m_SpriteID").stringValue;
    var iid = sp.FindPropertyRelative("m_InternalID").longValue;
    existingSprites[name] = new SpriteMeta { name = name, spriteID = sid, internalID = iid };
}
so.Dispose();

// Get current sprite rects from meta for reference
var currentRects = new Dictionary<string, Rect>();
var allSprites = AssetDatabase.LoadAllAssetRepresentationsAtPath(assetPath).OfType<Sprite>()
    .OrderBy(s => int.TryParse(s.name.Replace("Run_", ""), out var i) ? i : 0).ToArray();
foreach (var s in allSprites)
    currentRects[s.name] = s.rect;

Debug.Log($"Loaded {currentRects.Count} sprite rects");

// Need to read the texture to find content bounds per row
// Make it readable temporarily
importer.isReadable = true;
importer.textureType = TextureImporterType.Default;
importer.SaveAndReimport();

var tex = AssetDatabase.LoadAssetAtPath<Texture2D>(assetPath);
Debug.Log($"Texture size: {tex.width}x{tex.height}");
var pixels = tex.GetPixels32();

// For each row, compute the union bounding box of all frames
// Then create consistent rects
int texW = tex.width;
int texH = tex.height;

// Current rects give us the y-range per row
var rowDefs = new (string rowName, int yMin, int yMax, int[] frameIndices)[]
{
    ("Down",  0, 7,   Enumerable.Range(0, 8).ToArray()),
    ("Up",    8, 15,  Enumerable.Range(8, 8).ToArray()),
    ("Left", 16, 23,  Enumerable.Range(16, 8).ToArray()),
};

// Find per-row consistent rect: union of all frame rects in that row
var newSpriteMetas = new List<SpriteMetaNew>();

foreach (var (rowName, firstIdx, lastIdx, frameIndices) in rowDefs)
{
    // Get current rects for this row to find the row's vertical band
