using UnityEngine;
using UnityEditor;
using System.Collections.Generic;
using System.Linq;

public static class ResliceRun
{
    [MenuItem("Flynn/Reslice Run Spritesheet")]
    public static void Reslice()
    {
        var assetPath = "Assets/Flynn/Sprites/character_animations/FINAL_ANIMATIONS/RUN_NEW/Run.png";
        DoReslice(assetPath, "Run", 8, 3);
    }

    [MenuItem("Flynn/Reslice Idle Spritesheet")]
    public static void ResliceIdle()
    {
        DoReslice("Assets/Flynn/Sprites/character_animations/FINAL_ANIMATIONS/IDLE/Idle.png", "Idle", 8, 3);
    }

    private static void DoReslice(string assetPath, string prefix, int cols, int rows)
    {
        var importer = (TextureImporter)AssetImporter.GetAtPath(assetPath);
        if (importer == null) { Debug.LogError($"[Reslice] Not found: {assetPath}"); return; }

        // Read rects and spriteIDs from SerializedObject BEFORE touching the importer
        var existingMeta = new Dictionary<string, SpriteMeta>();
        var currentRects = new Dictionary<string, Rect>();
        var so = new SerializedObject(importer);
        var spriteSheetProp = so.FindProperty("m_SpriteSheet.m_Sprites");
        for (int i = 0; i < spriteSheetProp.arraySize; i++)
        {
            var sp = spriteSheetProp.GetArrayElementAtIndex(i);
            var name = sp.FindPropertyRelative("m_Name").stringValue;
            var sid = sp.FindPropertyRelative("m_SpriteID").stringValue;
            var iid = sp.FindPropertyRelative("m_InternalID").longValue;
            existingMeta[name] = new SpriteMeta { spriteID = sid, internalID = iid };

            var rectX = sp.FindPropertyRelative("m_Rect").FindPropertyRelative("x").floatValue;
            var rectY = sp.FindPropertyRelative("m_Rect").FindPropertyRelative("y").floatValue;
            var rectW = sp.FindPropertyRelative("m_Rect").FindPropertyRelative("width").floatValue;
            var rectH = sp.FindPropertyRelative("m_Rect").FindPropertyRelative("height").floatValue;
            currentRects[name] = new Rect(rectX, rectY, rectW, rectH);
        }
        so.Dispose();

        // Make readable for pixel scanning
        importer.isReadable = true;
        importer.SaveAndReimport();
        AssetDatabase.Refresh(ImportAssetOptions.ForceUpdate);

        var tex = AssetDatabase.LoadAssetAtPath<Texture2D>(assetPath);
        if (tex == null) { Debug.LogError("[Reslice] Texture is null after reimport"); return; }
        var pixels = tex.GetPixels32();
        int texW = tex.width;

        var newMetas = new List<SpriteMetaNew>();

        for (int row = 0; row < rows; row++)
        {
            var frameIndices = Enumerable.Range(row * cols, cols).ToArray();

            // Row vertical band
            int rowYMin = int.MaxValue, rowYMax = int.MinValue;
            foreach (var idx in frameIndices)
            {
                var r = currentRects[$"{prefix}_{idx}"];
                rowYMin = Mathf.Min(rowYMin, (int)r.yMin);
                rowYMax = Mathf.Max(rowYMax, (int)r.yMax);
            }
            int rowHeight = rowYMax - rowYMin;

            // Scan for unified horizontal content extent
            int unifiedXMin = int.MaxValue, unifiedXMax = int.MinValue;
            foreach (var idx in frameIndices)
            {
                var r = currentRects[$"{prefix}_{idx}"];
                int fxMin = (int)r.xMin, fxMax = (int)r.xMax;
                int fyMin = (int)r.yMin, fyMax = (int)r.yMax;
                for (int x = fxMin; x < fxMax; x++)
                {
                    bool hasContent = false;
                    for (int y = fyMin; y < fyMax; y++)
                    {
                        if (pixels[y * texW + x].a > 10) { hasContent = true; break; }
                    }
                    if (hasContent) { unifiedXMin = Mathf.Min(unifiedXMin, x); unifiedXMax = Mathf.Max(unifiedXMax, x + 1); }
                }
            }
            int pad = 4;
            unifiedXMin = Mathf.Max(0, unifiedXMin - pad);
            unifiedXMax = Mathf.Min(texW, unifiedXMax + pad);
            int unifiedWidth = unifiedXMax - unifiedXMin;

            Debug.Log($"[Reslice] Row {row}: y=[{rowYMin},{rowYMax}] h={rowHeight} x=[{unifiedXMin},{unifiedXMax}] w={unifiedWidth}");

            foreach (var idx in frameIndices)
            {
                var r = currentRects[$"{prefix}_{idx}"];
                float frameCenterX = r.x + r.width / 2f;
                float newX = Mathf.Round(frameCenterX - unifiedWidth / 2f);
                newX = Mathf.Clamp(newX, 0, texW - unifiedWidth);

                string name = $"{prefix}_{idx}";
                newMetas.Add(new SpriteMetaNew
                {
                    name = name,
                    rect = new Rect(newX, rowYMin, unifiedWidth, rowHeight),
                    spriteID = existingMeta.TryGetValue(name, out var m) ? m.spriteID : "",
                    internalID = existingMeta.TryGetValue(name, out var m2) ? m2.internalID : 0
                });
            }
        }

        // Apply via SerializedObject
        so = new SerializedObject(importer);
        spriteSheetProp = so.FindProperty("m_SpriteSheet.m_Sprites");
        spriteSheetProp.ClearArray();
        for (int i = 0; i < newMetas.Count; i++)
        {
            spriteSheetProp.InsertArrayElementAtIndex(i);
            var sp = spriteSheetProp.GetArrayElementAtIndex(i);
            var m = newMetas[i];
            sp.FindPropertyRelative("m_Name").stringValue = m.name;
            sp.FindPropertyRelative("m_Rect").FindPropertyRelative("x").floatValue = m.rect.x;
            sp.FindPropertyRelative("m_Rect").FindPropertyRelative("y").floatValue = m.rect.y;
            sp.FindPropertyRelative("m_Rect").FindPropertyRelative("width").floatValue = m.rect.width;
            sp.FindPropertyRelative("m_Rect").FindPropertyRelative("height").floatValue = m.rect.height;
            sp.FindPropertyRelative("m_Alignment").intValue = 7; // Bottom
            sp.FindPropertyRelative("m_Pivot").FindPropertyRelative("x").floatValue = 0.5f;
            sp.FindPropertyRelative("m_Pivot").FindPropertyRelative("y").floatValue = 0f;
            sp.FindPropertyRelative("m_Border").FindPropertyRelative("x").floatValue = 0;
            sp.FindPropertyRelative("m_Border").FindPropertyRelative("y").floatValue = 0;
            sp.FindPropertyRelative("m_Border").FindPropertyRelative("z").floatValue = 0;
            sp.FindPropertyRelative("m_Border").FindPropertyRelative("w").floatValue = 0;
            sp.FindPropertyRelative("m_SpriteID").stringValue = m.spriteID;
            sp.FindPropertyRelative("m_InternalID").longValue = m.internalID;
        }
        so.ApplyModifiedProperties();
        importer.textureType = TextureImporterType.Sprite;
        importer.spriteImportMode = SpriteImportMode.Multiple;
        importer.isReadable = false;

        // Delay the reimport so it doesn't block the menu call
        EditorApplication.delayCall += () =>
        {
            importer.SaveAndReimport();
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            Debug.Log($"[Reslice] {assetPath} done — consistent rects + bottom-center pivot.");

            // Recreate animation clips from updated sprites
            RebuildClips(assetPath, prefix, 8, 3);
        };
    }

    private static void RebuildClips(string sheetPath, string prefix, int cols, int rows)
    {
        const string animOut = "Assets/Flynn/Animations";
        const float fps = 12f;

        var allSprites = AssetDatabase.LoadAllAssetRepresentationsAtPath(sheetPath)
            .OfType<Sprite>()
            .OrderBy(s => { int.TryParse(s.name.Replace(prefix + "_", ""), out var i); return i; })
            .ToArray();

        string[] dirNames = { "Down", "Up", "Left" };
        string action = prefix == "Run" ? "Run" : "Idle";

        for (int row = 0; row < rows; row++)
        {
            string clipName = $"Flynn_{action}_{dirNames[row]}";
            int start = row * cols;
            int count = cols;

            var clip = new AnimationClip { frameRate = fps };
            var binding = new EditorCurveBinding
            {
                type = typeof(SpriteRenderer),
                path = "",
                propertyName = "m_Sprite"
            };
            var keys = new ObjectReferenceKeyframe[count];
            for (int i = 0; i < count; i++)
                keys[i] = new ObjectReferenceKeyframe { time = i / fps, value = allSprites[start + i] };

            AnimationUtility.SetObjectReferenceCurve(clip, binding, keys);
            var settings = AnimationUtility.GetAnimationClipSettings(clip);
            settings.loopTime = true;
            AnimationUtility.SetAnimationClipSettings(clip, settings);
            clip.wrapMode = WrapMode.Loop;

            string outPath = $"{animOut}/{clipName}.anim";
            if (AssetDatabase.LoadAssetAtPath<AnimationClip>(outPath) != null)
                AssetDatabase.DeleteAsset(outPath);
            AssetDatabase.CreateAsset(clip, outPath);
            EditorUtility.SetDirty(clip);
            Debug.Log($"[Reslice] Rebuilt clip '{clipName}' ({count} frames)");
        }

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
    }

    private struct SpriteMeta { public string spriteID; public long internalID; }
    private struct SpriteMetaNew { public string name; public Rect rect; public string spriteID; public long internalID; }
}

